#include <Arduino.h>
// 板载 LED：蓝药丸 PC13（低电平亮）、Nucleo PA5、UNO 13、ESP32 GPIO2（高电平亮）
// LED_BUILTIN 这个名字由开发板定义自动给出，不用自己查引脚

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);    // 先告诉芯片：这根脚我要当输出用
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH); // 输出高电平（3.3V 或 5V）
  delay(500);                      // 傻等 500 毫秒，期间芯片什么都干不了
  digitalWrite(LED_BUILTIN, LOW);  // 输出低电平（0V）
  delay(500);
}
// 看到灯在闪就说明：编译 OK、烧录 OK、板子活着。
// 蓝药丸上 HIGH 是灭、LOW 是亮，但一闪一灭的节奏是一样的。

#include <Arduino.h>
// 按键一脚接 PB12，另一脚接 GND。用芯片内部上拉：没按=高电平，按下=低电平
const int BTN = PB12;
const int LED = PC13;
const unsigned long DEBOUNCE_MS = 30;  // 机械抖动一般 5~20ms 内结束

int lastReading = HIGH;         // 上一次的原始读数
int stableState = HIGH;         // 去抖后承认的稳定状态
unsigned long lastChange = 0;   // 原始读数最后一次变化的时刻
unsigned long pressCount = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);   // 内部上拉，省一个电阻
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int reading = digitalRead(BTN);
  if (reading != lastReading) {   // 原始读数一变，就重新开始计时
    lastChange = millis();
    lastReading = reading;
  }
  // 读数保持不变超过 DEBOUNCE_MS，才承认它是真的
  if (millis() - lastChange > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;
    if (stableState == LOW) {     // 只在"刚按下"这一瞬间计数
      pressCount++;
      Serial.print("按下次数: ");
      Serial.println(pressCount);
    }
  }
  digitalWrite(LED, stableState); // 按下(LOW)时 PC13 低电平，灯亮
}

#include <Arduino.h>
// 按键 PB12 接 GND，内部上拉。每按一次，LED 状态翻转一次
const int BTN = PB12;
const int LED = PC13;

bool ledOn = false;             // 我们自己记住的"当前状态"
int lastStable = HIGH;          // 上一次承认的按键状态
int lastReading = HIGH;
unsigned long lastChange = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  digitalWrite(LED, HIGH);      // PC13 高电平=灭
}

void loop() {
  int reading = digitalRead(BTN);
  if (reading != lastReading) { lastChange = millis(); lastReading = reading; }

  if (millis() - lastChange > 30 && reading != lastStable) {
    lastStable = reading;
    if (lastStable == LOW) {    // 检测"下降沿"：从没按到按下的瞬间
      ledOn = !ledOn;           // 翻转状态
      digitalWrite(LED, ledOn ? LOW : HIGH);  // PC13 低电平亮
    }
  }
}

#include <Arduino.h>
// 外接 LED：PA8 → 220Ω 电阻 → LED 长脚，LED 短脚 → GND
// PC13 板载灯背后没有定时器，analogWrite 不起作用，所以要外接一个
const int LED = PA8;

void setup() {
  pinMode(LED, OUTPUT);
  analogWriteFrequency(1000);   // STM32duino 专有：PWM 频率设 1kHz，人眼看不出闪
  analogWriteResolution(8);     // 0~255 共 256 级
}

void loop() {
  for (int duty = 0; duty <= 255; duty++) {   // 渐亮
    analogWrite(LED, duty);   // duty=0 全灭，255 全亮，128 大概半亮
    delay(4);
  }
  for (int duty = 255; duty >= 0; duty--) {   // 渐暗
    analogWrite(LED, duty);
    delay(4);
  }
}
// 想要更像"呼吸"的曲线：亮度用 duty*duty/255 代替 duty（人眼对暗部更敏感）

#include <Arduino.h>
// 电位器：两端分别接 3.3V 和 GND，中间脚接 PA0
const int POT = PA0;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);  // STM32 的 ADC 是 12 位：0~4095（默认按 10 位给 0~1023）
}

void loop() {
  int raw = analogRead(POT);

  // map(值, 原范围低, 原范围高, 新范围低, 新范围高)：把 0~4095 换算成 0~100
  int percent = map(raw, 0, 4095, 0, 100);

  // 换算成电压：raw / 4095 * 3.3V。用 float 和 3.3f，不然整数除法结果全是 0
  float volts = raw * 3.3f / 4095.0f;

  Serial.print("raw=");
  Serial.print(raw);
  Serial.print("  ");
  Serial.print(percent);
  Serial.print("%  ");
  Serial.print(volts, 2);    // 保留两位小数
  Serial.println("V");
  delay(200);
}

#include <Arduino.h>
// 在串口监视器输入 on / off / ? 再回车（监视器要设成"发送换行 \n"）
// 蓝药丸的 Serial 是 PA9(TX)/PA10(RX)，要接 USB-TTL 模块；Nucleo/UNO/ESP32 直接 USB
String cmd = "";

void handle(String c) {
  c.trim();                  // 去掉两头的空格和回车换行
  if (c == "on")       digitalWrite(LED_BUILTIN, HIGH);
  else if (c == "off") digitalWrite(LED_BUILTIN, LOW);
  else if (c == "?")   Serial.println("命令：on off ?");
  else { Serial.print("不认识: "); Serial.println(c); return; }
  Serial.print("OK ");
  Serial.println(c);
}

void setup() {
  Serial.begin(115200);      // 波特率要和 platformio.ini 的 monitor_speed 一致
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.println("就绪。输入 on / off / ? 回车");
}

void loop() {
  while (Serial.available()) {          // 缓冲区里有字节就取出来
    char ch = Serial.read();
    if (ch == '\n') {                   // 收到换行，说明一条命令收完了
      handle(cmd);
      cmd = "";
    } else if (cmd.length() < 32) {     // 限长，防止乱输一堆把内存撑爆
      cmd += ch;
    }
  }
}

#include <Arduino.h>
// 两件事按各自的节奏跑：LED 每 250ms 翻转一次，串口每 2 秒报一次心跳
// 核心思想：不"等"，而是每圈问一句"到点了吗？"

unsigned long lastBlink = 0;
unsigned long lastReport = 0;
const unsigned long BLINK_MS = 250;
const unsigned long REPORT_MS = 2000;
bool ledState = false;
unsigned long loops = 0;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  unsigned long now = millis();   // 上电到现在的毫秒数，一圈只取一次
  loops++;

  if (now - lastBlink >= BLINK_MS) {      // 任务 1：闪灯
    lastBlink = now;
    ledState = !ledState;
    digitalWrite(LED_BUILTIN, ledState);
  }

  if (now - lastReport >= REPORT_MS) {    // 任务 2：报心跳
    lastReport = now;
    Serial.print("alive, loop 每秒跑了约 ");
    Serial.print(loops / (REPORT_MS / 1000));
    Serial.println(" 圈");
    loops = 0;
  }
  // 这里还能再塞任务 3、4、5，谁也不会卡谁。以后按键、传感器都这么写
}

#include <Arduino.h>
// 三个 LED 各串 220Ω：红 PB0、黄 PB1、绿 PB10，另一端接 GND
const int RED = PB0, YELLOW = PB1, GREEN = PB10;

enum State { S_RED, S_GREEN, S_YELLOW };   // 把"现在处于哪个阶段"起个名
State state = S_RED;
unsigned long enteredAt = 0;               // 进入当前状态的时刻

// 每个状态各停多久（毫秒）
unsigned long durationOf(State s) {
  switch (s) {
    case S_RED:    return 3000;
    case S_GREEN:  return 3000;
    case S_YELLOW: return 1000;
  }
  return 1000;
}

void showLights(State s) {
  digitalWrite(RED,    s == S_RED);
  digitalWrite(YELLOW, s == S_YELLOW);
  digitalWrite(GREEN,  s == S_GREEN);
}

void setup() {
  pinMode(RED, OUTPUT); pinMode(YELLOW, OUTPUT); pinMode(GREEN, OUTPUT);
  showLights(state);
  enteredAt = millis();
}

void loop() {
  if (millis() - enteredAt >= durationOf(state)) {   // 当前状态时间到了
    if (state == S_RED)         state = S_GREEN;      // 状态转移表
    else if (state == S_GREEN)  state = S_YELLOW;
    else                        state = S_RED;
    enteredAt = millis();
    showLights(state);
  }
  // loop 其余时间是空闲的，可以同时处理按键、串口
}

#include <Arduino.h>
// 按键或脉冲信号接 PB12，另一端接 GND，内部上拉。每来一个下降沿就计数一次
const int PIN = PB12;

volatile uint32_t count = 0;   // volatile：告诉编译器这个变量会被中断"偷偷"改，别优化

void onFalling() {             // 中断服务函数：越短越好，不要 Serial、不要 delay
  count++;
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN, INPUT_PULLUP);
  // 把"PB12 出现下降沿"这件事和 onFalling 绑定。FALLING=高变低，RISING=低变高，CHANGE=都算
  attachInterrupt(digitalPinToInterrupt(PIN), onFalling, FALLING);
}

void loop() {
  static unsigned long last = 0;
  if (millis() - last >= 1000) {
    last = millis();
    noInterrupts();            // 读多字节变量时先关中断，防止读到一半被改
    uint32_t snapshot = count;
    interrupts();
    Serial.print("这一秒到现在总计: ");
    Serial.println(snapshot);
  }
}
// 用手按按键会发现一次按下计了好几下，那是抖动，见"中断+millis 去抖"那条

#include <Arduino.h>
// 硬件定时器：芯片里的独立计数器到点自动调回调，不占 loop，也不受 loop 快慢影响
// F103 有 TIM1~TIM4。TIM1 高级、TIM2~4 通用，这里用 TIM2
HardwareTimer timer(TIM2);
volatile uint32_t ticks = 0;

void onTick() {                     // 回调跑在中断里：要短，别 Serial、别 delay
  digitalWrite(PC13, !digitalRead(PC13));   // 翻转板载 LED
  ticks++;
}

void setup() {
  pinMode(PC13, OUTPUT);
  Serial.begin(115200);

  timer.setOverflow(2, HERTZ_FORMAT);   // 每秒溢出 2 次 = 每 500ms 调一次回调
  // 也可以写 timer.setOverflow(500000, MICROSEC_FORMAT);  单位微秒
  timer.attachInterrupt(onTick);
  timer.resume();                       // 开始计时。pause() 可以暂停
}

void loop() {
  static uint32_t last = 0;
  if (millis() - last >= 1000) {
    last = millis();
    Serial.print("定时器已触发 ");
    Serial.print(ticks);
    Serial.println(" 次");
  }
  // loop 可以随便 delay，LED 照样准时闪，这就是硬件定时器的价值
}

#include <Arduino.h>
#include <Wire.h>
// 蓝药丸默认 I2C1 是 SCL PB6 / SDA PB7；本课程用 PB8/PB9 时取消下面两行注释
// Nucleo: SCL D15 / SDA D14；UNO: A5 / A4；ESP32: 22 / 21

void setup() {
  Serial.begin(115200);
  // Wire.setSDA(PB9); Wire.setSCL(PB8);   // 仅 STM32duino 有这两个函数
  Wire.begin();
  delay(500);
  Serial.println("开始扫描 I2C 总线...");
}

void loop() {
  int found = 0;
  for (uint8_t addr = 1; addr < 127; addr++) {   // 7 位地址范围 0x01~0x7E
    Wire.beginTransmission(addr);                // 敲一下这个地址
    uint8_t err = Wire.endTransmission();        // 0 表示有人应答
    if (err == 0) {
      Serial.print("  发现设备: 0x");
      if (addr < 16) Serial.print("0");
      Serial.println(addr, HEX);
      found++;
    }
  }
  if (found == 0) Serial.println("  一个都没找到：检查 SDA/SCL 有没有接反、有没有共地、模块有没有上电");
  Serial.println("5 秒后再扫一次");
  delay(5000);
}
// 常见地址：OLED SSD1306 0x3C / 0x3D，DS3231 0x68，AT24C32 0x57，MPU6050 0x68，BMP280 0x76

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>
// 0.96 寸 OLED（SSD1306，I2C 地址 0x3C）：VCC→3.3V，GND→GND，SCL→PB8，SDA→PB9
// 类名的意思：驱动 SSD1306，128x64，无名牌子，F=全缓冲，HW_I2C=硬件 I2C
U8G2_SSD1306_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

int counter = 0;

void setup() {
  Wire.setSDA(PB9);           // 蓝药丸默认 I2C 在 PB6/PB7，这里改到 PB8/PB9
  Wire.setSCL(PB8);
  u8g2.begin();               // 内部会调 Wire.begin()
}

void loop() {
  u8g2.clearBuffer();                          // 先清内存里的画布
  u8g2.setFont(u8g2_font_ncenB10_tr);          // 选字体（英文数字）
  u8g2.drawStr(0, 14, "Hello STM32");          // (x, y) 是文字基线左下角
  u8g2.setFont(u8g2_font_6x12_tr);
  u8g2.setCursor(0, 32);
  u8g2.print("count = ");
  u8g2.print(counter);
  u8g2.drawFrame(0, 40, 128, 12);              // 画一个空心框
  u8g2.drawBox(2, 42, map(counter % 100, 0, 99, 0, 124), 8);   // 进度条
  u8g2.sendBuffer();                           // 一次性把画布推到屏幕
  counter++;
  delay(100);
}
// 显示中文：setFont(u8g2_font_wqy12_t_gb2312) + drawUTF8()，但字库约 100KB+，F103C8 放不下

#include <Arduino.h>
#include <DHT.h>
// DHT11 三线模块：VCC→3.3V（或 5V），GND→GND，DATA→PB5
// 裸的四脚 DHT11 要在 DATA 和 VCC 之间加 10kΩ 上拉，模块一般自带
#define DHT_PIN  PB5
#define DHT_TYPE DHT11        // DHT22 更精确，改这里即可

DHT dht(DHT_PIN, DHT_TYPE);

void setup() {
  Serial.begin(115200);
  dht.begin();
  Serial.println("DHT11 需要上电后等 1~2 秒才能读");
}

void loop() {
  delay(2000);                              // DHT11 每次读之间至少隔 1 秒
  float h = dht.readHumidity();
  float t = dht.readTemperature();          // 摄氏度

  if (isnan(h) || isnan(t)) {               // 读失败会返回 NaN（不是数字）
    Serial.println("读取失败：检查接线、上拉电阻，或者刚上电还没准备好");
    return;
  }
  Serial.print("温度 ");
  Serial.print(t, 1);
  Serial.print(" C   湿度 ");
  Serial.print(h, 0);
  Serial.println(" %");
}

#include <Arduino.h>
#include <OneWire.h>
#include <DallasTemperature.h>
// DS18B20：VDD→3.3V，GND→GND，DQ→PA1，并且 DQ 和 3.3V 之间接 4.7kΩ 上拉（必须！）
// 防水探头三根线：红 VDD，黑 GND，黄 DQ
const int ONE_WIRE_PIN = PA1;

OneWire oneWire(ONE_WIRE_PIN);
DallasTemperature sensors(&oneWire);

void setup() {
  Serial.begin(115200);
  sensors.begin();
  Serial.print("总线上找到 ");
  Serial.print(sensors.getDeviceCount());
  Serial.println(" 个 DS18B20");
  sensors.setResolution(12);              // 9~12 位，12 位 0.0625°C，转换要 750ms
}

void loop() {
  sensors.requestTemperatures();          // 让所有探头开始转换（会阻塞约 750ms）
  float t = sensors.getTempCByIndex(0);   // 取第 0 个探头的摄氏度

  if (t == DEVICE_DISCONNECTED_C) {       // -127 表示没读到
    Serial.println("没找到探头：查上拉电阻和接线");
  } else {
    Serial.print("温度: ");
    Serial.print(t, 2);
    Serial.println(" C");
  }
  delay(1000);
}
// 多个探头：getTempCByIndex(1)、(2)...；正式项目用 getAddress 记住每个探头的 64 位序列号

#include <Arduino.h>
#include <Servo.h>
// SG90 舵机：棕线→GND，红线→5V（板子的 5V 排针或独立电源），橙线→PA8
// 舵机的 GND 必须和板子共地
Servo myServo;
const int SERVO_PIN = PA8;

void setup() {
  Serial.begin(115200);
  myServo.attach(SERVO_PIN);   // 绑定引脚，库会用一个定时器产生 50Hz 的脉冲
  myServo.write(90);           // 先回中间
  delay(500);
}

