  myServo.write(0);            // 转到 0 度
  Serial.println("0");
  delay(1000);                 // 给它时间转过去，SG90 转 180 度约 0.5 秒

  myServo.write(90);
  Serial.println("90");
  delay(1000);

  myServo.write(180);
  Serial.println("180");
  delay(1000);
}
// 角度不对时可以校准脉宽：myServo.attach(SERVO_PIN, 500, 2500);  // 最小/最大微秒
// 不用时 myServo.detach() 可以让它松开、不再抖动发热

#include <Arduino.h>
// HC-SR04：VCC→5V，GND→GND，TRIG→PB10，ECHO→PB11
// ECHO 输出 5V 高电平，PB10/PB11 是 5V 耐受脚所以能直接接；别接 PA0~PA7
const int TRIG = PB10;
const int ECHO = PB11;

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  digitalWrite(TRIG, LOW);
}

float readDistanceCm() {
  digitalWrite(TRIG, HIGH);                   // 给 10 微秒的触发脉冲
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  // 等 ECHO 变高并测量它保持高的时间（微秒），超过 30ms 没回来就放弃
  unsigned long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;                     // 超时：太远或没接好

  // 声速约 343m/s = 0.0343cm/us，来回走了两趟所以除 2
  return us * 0.0343f / 2.0f;
}

void loop() {
  float d = readDistanceCm();
  if (d < 0) Serial.println("超出量程（>4m）或没接好");
  else {
    Serial.print("距离: ");
    Serial.print(d, 1);
    Serial.println(" cm");
  }
  delay(100);                                 // 两次测量至少隔 60ms，避免回波串扰
}

#include <Arduino.h>
// 无源蜂鸣器：正极（长脚或标 +）→PA8，负极→GND
// 有源蜂鸣器只会一个音，直接 digitalWrite 高低就响/停，不用 tone
const int BUZZER = PA8;

// 音符频率（Hz）：do re mi fa so la si do
const int NOTES[] = {262, 294, 330, 349, 392, 440, 494, 523};

void setup() {
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  for (int i = 0; i < 8; i++) {
    tone(BUZZER, NOTES[i], 200);   // 引脚, 频率, 持续毫秒（不阻塞）
    delay(250);                    // 音符之间留 50ms 空隙，听起来才分得开
  }
  noTone(BUZZER);                  // 停
  delay(500);

  // 报警声：两个频率来回切
  for (int i = 0; i < 3; i++) {
    tone(BUZZER, 800);  delay(150);
    tone(BUZZER, 1200); delay(150);
  }
  noTone(BUZZER);
  delay(2000);
}

#include <Arduino.h>
// 继电器模块：VCC→5V，GND→GND，IN→PB12。负载接在 COM 和 NO（常开）上
// MOS 管模块：VCC/GND 同上，SIG→PB12，负载接 V+ / V-。二者代码一样
const int SWITCH_PIN = PB12;

// 很多继电器模块是"低电平触发"（IN 为低时吸合）。先按模块丝印改这个
const bool ACTIVE_LOW = true;

void turnOn()  { digitalWrite(SWITCH_PIN, ACTIVE_LOW ? LOW : HIGH); }
void turnOff() { digitalWrite(SWITCH_PIN, ACTIVE_LOW ? HIGH : LOW); }

void setup() {
  Serial.begin(115200);
  pinMode(SWITCH_PIN, OUTPUT);
  turnOff();                    // 上电第一件事：确保负载是关的
  Serial.println("每 3 秒切换一次，听继电器咔哒声");
}

void loop() {
  turnOn();
  Serial.println("ON");
  delay(3000);

  turnOff();
  Serial.println("OFF");
  delay(3000);
}
