#include <Arduino.h>
#include <FastLED.h>
// WS2812B 灯带三根线：5V→外部 5V 电源，GND→共地，DIN→DATA_PIN（串 330Ω 电阻更稳）
// 蓝药丸把 DATA_PIN 改成 PA7，UNO 用 6，ESP32 用 13。8 颗灯可以从板子 5V 供，再多要独立供电
#define DATA_PIN  6
#define NUM_LEDS  8

CRGB leds[NUM_LEDS];              // 内存里的颜色数组，一个元素一颗灯

void setup() {
  FastLED.addLeds<WS2812B, DATA_PIN, GRB>(leds, NUM_LEDS);  // GRB 是 WS2812B 的颜色顺序
  FastLED.setBrightness(40);      // 0~255，先调低，全亮很刺眼也很耗电
}

void loop() {
  // 效果 1：彩虹流动
  static uint8_t hue = 0;
  for (int i = 0; i < NUM_LEDS; i++) {
    leds[i] = CHSV(hue + i * 32, 255, 255);   // 色相、饱和度、亮度
  }
  FastLED.show();                             // 改完数组后必须 show 才会发到灯带
  hue += 2;
  delay(20);
}
// 效果 2：单个红点 leds[3] = CRGB::Red;  清空 FastLED.clear();  都要跟 FastLED.show()

#include <Arduino.h>
#include <Wire.h>
#include <RTClib.h>
// DS3231 模块：VCC→3.3V，GND→GND，SCL/SDA→板子的 I2C 脚（蓝药丸 PB8/PB9 需 setSCL/setSDA）
RTC_DS3231 rtc;

const int ALARM_HOUR = 7, ALARM_MINUTE = 30;   // 每天触发的时刻
bool firedToday = false;                        // 防止同一分钟里反复触发

void setup() {
  Serial.begin(115200);
  if (!rtc.begin()) { Serial.println("找不到 DS3231，查 I2C 接线"); while (1) delay(10); }
  if (rtc.lostPower()) {                        // 电池没电或第一次用：用编译时间校准
    Serial.println("RTC 时间丢失，用编译时间设置");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  DateTime now = rtc.now();
  char buf[20];
  snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d",
           now.year(), now.month(), now.day(), now.hour(), now.minute(), now.second());
  Serial.println(buf);

  bool isAlarmTime = (now.hour() == ALARM_HOUR && now.minute() == ALARM_MINUTE);
  if (isAlarmTime && !firedToday) {
    firedToday = true;
    Serial.println(">>> 到点了！这里放要做的事（喂食、开灯）");
  }
  if (!isAlarmTime) firedToday = false;         // 过了那一分钟就复位，明天还能触发

  Serial.print("模块温度 "); Serial.println(rtc.getTemperature());
  delay(1000);
}

#include <Arduino.h>
// 电位器：两端接 3.3V 和 GND，中间脚接 PA0
// LED：PA8 → 220Ω → LED → GND
const int POT = PA0;
const int LED = PA8;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);     // 读 0~4095
  analogWriteResolution(8);     // 写 0~255
  pinMode(LED, OUTPUT);
}

void loop() {
  int raw = analogRead(POT);                 // 0~4095

  // 简单平滑：新值只占 1/4，旧值占 3/4，去掉旋钮抖动
  static int smooth = 0;
  smooth = (smooth * 3 + raw) / 4;

  int duty = map(smooth, 0, 4095, 0, 255);   // 换算到 PWM 范围
  duty = (duty * duty) / 255;                // 平方曲线，让暗部变化更明显
  analogWrite(LED, duty);

  Serial.print(raw);
  Serial.print(" -> ");
  Serial.println(duty);
  delay(20);
}

#include <Arduino.h>
// 光敏电阻分压：3.3V → 光敏电阻 → PA1（同时）→ 10kΩ 电阻 → GND
// 亮的时候光敏电阻变小，PA1 电压升高；暗的时候电阻变大，PA1 电压降低
const int LDR = PA1;
const int LED = PC13;
const int DARK_THRESHOLD = 1200;   // 低于它算天黑。先跑一遍看串口，按你环境改

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  pinMode(LED, OUTPUT);
}

void loop() {
  long sum = 0;
  for (int i = 0; i < 16; i++) sum += analogRead(LDR);   // 采 16 次取平均，抗噪
  int light = sum / 16;

  // 加一点"回差"：低于 1200 算暗，要高于 1400 才算重新亮，避免在临界值附近闪
  static bool dark = false;
  if (!dark && light < DARK_THRESHOLD)        dark = true;
  else if (dark && light > DARK_THRESHOLD + 200) dark = false;

  digitalWrite(LED, dark ? LOW : HIGH);       // PC13 低电平亮：天黑开灯
  Serial.print("light=");
  Serial.print(light);
  Serial.println(dark ? "  暗" : "  亮");
  delay(200);
}

#include <Arduino.h>
#include <IWatchdog.h>
// 独立看门狗（IWDG）：一个倒计时器，你必须定期"喂狗"把它重置，
// 忘了喂（说明程序卡住了）它就把芯片复位。一旦启动就关不掉，直到断电

void setup() {
  Serial.begin(115200);
  pinMode(PC13, OUTPUT);
  delay(200);
  if (IWatchdog.isReset()) {           // 判断这次上电是不是被狗咬的
    Serial.println("!!! 上次是看门狗复位，说明程序卡死过");
    IWatchdog.clearReset();
  } else {
    Serial.println("正常上电");
  }
  IWatchdog.begin(2000000);            // 单位微秒：2 秒内不喂就复位（最长约 32 秒）
}

void loop() {
  static unsigned long bootMs = millis();
  digitalWrite(PC13, !digitalRead(PC13));
  Serial.print("运行 ");
  Serial.print((millis() - bootMs) / 1000);
  Serial.println(" 秒");
  delay(500);
  IWatchdog.reload();                  // 喂狗：告诉它"我还活着"

  // 演示：运行 10 秒后故意死循环，不再喂狗，2 秒后你会看到板子自己重启
  if (millis() - bootMs > 10000) {
    Serial.println("模拟卡死...");
    while (1) { }
  }
}

#include <Arduino.h>
#include <STM32LowPower.h>
// 每 5 秒醒一次：闪一下灯、打印一句，然后深睡。深睡时 F103 电流从约 30mA 降到 1mA 以下
// 需要 STM32duino Low Power 和 STM32duino RTC 两个库（睡眠靠 RTC 定时唤醒）

void setup() {
  Serial.begin(115200);
  pinMode(PC13, OUTPUT);
  digitalWrite(PC13, HIGH);          // 灭
  LowPower.begin();                  // 初始化低功耗子系统（内部会启动 RTC）
  Serial.println("开始：工作 200ms，睡 5 秒，循环");
}

void loop() {
  digitalWrite(PC13, LOW);           // 醒着：亮灯 200ms
  Serial.print("醒了，millis=");
  Serial.println(millis());
  Serial.flush();                    // 等串口把字发完再睡，否则半句话就断了
  delay(200);
  digitalWrite(PC13, HIGH);

  LowPower.deepSleep(5000);          // 深睡 5000ms，RTC 到点自动唤醒，从这一行继续往下跑
  // 还有 LowPower.sleep(ms)：睡得浅、醒得快、省得少
  // LowPower.shutdown(ms)：睡得最深，但醒来等于复位，从 setup 重新开始
}
// 按键唤醒：LowPower.attachInterruptWakeup(PA0, callback, FALLING);  然后 deepSleep() 不带参数

#include <Arduino.h>
#include <EEPROM.h>
// STM32 没有真正的 EEPROM，STM32duino 用 Flash 最后一页模拟。API 和 UNO 的 EEPROM 一样
// 这里记录"板子一共上电了几次"

struct Settings {
  uint32_t magic;        // 固定标记，用来判断存过没有（第一次用时 Flash 里是垃圾）
  uint32_t bootCount;
  float    calibration;  // 顺便示范存个浮点
};
const uint32_t MAGIC = 0xA5A5C001;
const int ADDR = 0;      // 存放地址

void setup() {
  Serial.begin(115200);
  delay(300);

  Settings s;
  EEPROM.get(ADDR, s);                 // 把 ADDR 开始的一段字节读进结构体
  if (s.magic != MAGIC) {              // 第一次：初始化
    Serial.println("没有存过，初始化");
    s.magic = MAGIC;
    s.bootCount = 0;
    s.calibration = 1.0f;
  }
  s.bootCount++;
  EEPROM.put(ADDR, s);                 // 写回。STM32 上这一步会擦写一整页 Flash，约几十毫秒

  Serial.print("这是第 ");
  Serial.print(s.bootCount);
  Serial.println(" 次上电");
  Serial.print("校准值 ");
  Serial.println(s.calibration);
}

void loop() {
  // 按复位键，看计数一直加。改 calibration 也一样 put 一下
}

