#include <Arduino.h>
// 按键 PB12 接 GND，内部上拉。用中断捕获下降沿，在中断里用时间戳过滤抖动
const int BTN = PB12;
const unsigned long DEBOUNCE_MS = 50;

volatile uint32_t presses = 0;
volatile unsigned long lastIsrMs = 0;

void onPress() {
  unsigned long now = millis();       // millis 在中断里可以读（它只是读一个计数器）
  if (now - lastIsrMs < DEBOUNCE_MS) return;   // 距离上次太近，是抖动，忽略
  lastIsrMs = now;
  presses++;
}

void setup() {
  Serial.begin(115200);
  pinMode(BTN, INPUT_PULLUP);
  pinMode(PC13, OUTPUT);
  attachInterrupt(digitalPinToInterrupt(BTN), onPress, FALLING);
}

void loop() {
  static uint32_t shown = 0;
  if (presses != shown) {             // 计数变了才打印，loop 里不做别的
    shown = presses;
    Serial.print("按键次数: ");
    Serial.println(shown);
    digitalWrite(PC13, !digitalRead(PC13));
  }
  delay(100);                         // 故意放个 delay 证明按键不受 loop 影响
}

#include <Arduino.h>
#include <Keypad.h>
// 4x4 薄膜键盘 8 根线：左 4 根是行（R1~R4），右 4 根是列（C1~C4）。不确定就用万用表测
// 16 个键只用 8 根 IO：轮流让一行输出低，看哪一列变低，就知道按的是哪个
const byte ROWS = 4, COLS = 4;
char keys[ROWS][COLS] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};
byte rowPins[ROWS] = {PB12, PB13, PB14, PB15};   // 行接这里
byte colPins[COLS] = {PB5, PB6, PB7, PA8};       // 列接这里

Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);
String input = "";

void setup() {
  Serial.begin(115200);
  Serial.println("按键盘，# 结束输入，* 清空");
}

void loop() {
  char k = keypad.getKey();          // 没按返回 0（NO_KEY），库内部已做去抖
  if (!k) return;

  if (k == '#') {
    Serial.print("输入完成: ");
    Serial.println(input);
    if (input == "1234") Serial.println("密码正确");
    input = "";
  } else if (k == '*') {
    input = "";
    Serial.println("已清空");
  } else {
    input += k;
    Serial.print("当前: ");
    Serial.println(input);
  }
}

#include <Arduino.h>
// 示意：PA1 读温度传感器（这里假设 LM35 类线性传感器，10mV/°C），PA8 PWM 控制加热片（经 MOS 管）
// 换成 DS18B20 只需替换 readTemp()。目标 40°C
const int TEMP_PIN = PA1;
const int HEAT_PIN = PA8;
const float TARGET = 40.0f;

// 三个系数：先只调 Kp（大了振荡、小了到不了），再加一点 Ki 消除稳态误差，Kd 最后加
float Kp = 20.0f, Ki = 0.5f, Kd = 5.0f;
float integral = 0, lastError = 0;

float readTemp() {
  int raw = analogRead(TEMP_PIN);            // 12 位
  return raw * 3.3f / 4095.0f * 100.0f;      // LM35: 0.01V/°C
}

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  pinMode(HEAT_PIN, OUTPUT);
}

void loop() {
  static unsigned long last = 0;
  const float DT = 0.5f;                     // 控制周期 0.5 秒
  if (millis() - last < DT * 1000) return;
  last = millis();

  float temp = readTemp();
  float error = TARGET - temp;               // 差多少
  integral += error * DT;                    // 累积误差（消除长期偏差）
  integral = constrain(integral, -50, 50);   // 抗饱和：别让积分无限涨
  float derivative = (error - lastError) / DT;   // 变化趋势（提前刹车）
  lastError = error;

  float output = Kp * error + Ki * integral + Kd * derivative;
  int duty = constrain((int)output, 0, 255); // 加热只能 0~255，不能"负加热"
  analogWrite(HEAT_PIN, duty);

  Serial.print(temp); Serial.print(","); Serial.print(TARGET); Serial.print(","); Serial.println(duty);
}

#include <Arduino.h>
#include <Servo.h>
// SG90：棕→GND，红→5V，橙→PA8
Servo sweeper;
const int SERVO_PIN = PA8;
const int STEP_MS = 15;         // 每步等 15ms，一次 0→180 约 2.7 秒

int angle = 0;
int direction = 1;              // +1 往 180 走，-1 往 0 走
unsigned long lastStep = 0;

void setup() {
  Serial.begin(115200);
  sweeper.attach(SERVO_PIN);
  sweeper.write(angle);
}

void loop() {
  if (millis() - lastStep >= STEP_MS) {   // 每 15ms 挪一度，不用 delay
    lastStep = millis();
    angle += direction;
    if (angle >= 180) { angle = 180; direction = -1; }   // 到头就掉头
    if (angle <= 0)   { angle = 0;   direction = 1;  }
    sweeper.write(angle);
  }

  // 这里可以同时读超声波、按键、串口。比如按键让它停在当前角度：
  // if (digitalRead(PB12) == LOW) direction = 0;
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint >= 500) {
    lastPrint = millis();
    Serial.print("角度 ");
    Serial.println(angle);
  }
}

#include <Arduino.h>
#include <Stepper.h>
// 28BYJ-48 五线步进电机 + ULN2003 驱动板
// 驱动板 IN1→PB12，IN2→PB13，IN3→PB14，IN4→PB15；驱动板 +/- 接 5V/GND（和板子共地）
// 电机的白色插头直接插驱动板
const int STEPS_PER_REV = 2048;   // 全步模式：32 步 × 64 减速比 = 2048 步一圈

// 注意参数顺序是 IN1, IN3, IN2, IN4（不是 1234），这是 28BYJ 的线序特点
Stepper motor(STEPS_PER_REV, PB12, PB14, PB13, PB15);

void setup() {
  Serial.begin(115200);
  motor.setSpeed(12);             // 转速 RPM，这电机最高大约 15，再高会丢步
}

void loop() {
  Serial.println("正转一圈");
  motor.step(STEPS_PER_REV);      // 正数正转，阻塞直到转完（约 5 秒）
  delay(500);

  Serial.println("反转半圈");
  motor.step(-STEPS_PER_REV / 2);
  delay(500);

  Serial.println("转 90 度");
  motor.step(STEPS_PER_REV / 4);
  delay(2000);
}
// 停下来不需要保持力矩时，把四个 IN 都写 LOW 可以省电、不发热

#include <Arduino.h>
// HC-05/HC-06 蓝牙串口模块：VCC→5V，GND→GND，TXD→PA3（板子 RX），RXD→PA2（板子 TX）
// 模块 RXD 是 3.3V 逻辑，蓝药丸 TX 是 3.3V 正好；UNO 的 5V TX 要串分压
// 手机装"Serial Bluetooth Terminal"，配对密码 1234 或 0000，发 1 开灯，0 关灯
// 用 USART2 当蓝牙口：RX=PA3，TX=PA2。Serial 仍是 PA9/PA10 给电脑看
#if defined(ARDUINO_API_VERSION)  // STM32duino 3.x 起串口类改名叫 Uart
Uart BT(PA3, PA2);
#else                             // STM32duino 2.x 叫 HardwareSerial
HardwareSerial BT(PA3, PA2);
#endif

void setup() {
  Serial.begin(115200);           // 电脑
  BT.begin(9600);                 // 蓝牙模块默认 9600（HC-05 有的是 38400，看模块说明）
  pinMode(PC13, OUTPUT);
  digitalWrite(PC13, HIGH);
  Serial.println("等待蓝牙命令...");
}

void loop() {
  if (BT.available()) {
    char c = BT.read();
    Serial.print("收到: ");
    Serial.println(c);
    if (c == '1') {
      digitalWrite(PC13, LOW);    // 亮
      BT.println("LED ON");       // 回复给手机
    } else if (c == '0') {
      digitalWrite(PC13, HIGH);
      BT.println("LED OFF");
    }
  }
  // 电脑串口输入的东西转发给手机，方便调试
  if (Serial.available()) BT.write(Serial.read());
}

#include <Arduino.h>
#include <WiFi.h>
// ESP32 自带 WiFi，不需要任何库。改下面两行为你家路由器的名字和密码（只支持 2.4GHz）
const char* WIFI_SSID = "你的WiFi名";
const char* WIFI_PASS = "你的WiFi密码";

void connectWiFi() {
  Serial.print("连接 ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);                     // 作为客户端连路由器（不是自己开热点）
  WiFi.begin(WIFI_SSID, WIFI_PASS);

  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED) {  // 等连上，最多等 15 秒
    delay(500);
    Serial.print(".");
    if (millis() - start > 15000) {
      Serial.println("\n连不上：检查名字密码，路由器是不是 5GHz 专用");
      return;
    }
  }
  Serial.println();
  Serial.print("已连接，IP: ");
  Serial.println(WiFi.localIP());          // 之后做网页服务器就访问这个地址
  Serial.print("信号强度 RSSI: ");
  Serial.println(WiFi.RSSI());             // -50 很好，-80 很差
}

void setup() {
  Serial.begin(115200);
  delay(500);
  connectWiFi();
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {     // 掉线自动重连
    Serial.println("WiFi 掉了，重连");
    connectWiFi();
  }
  delay(5000);
}

#include <Arduino.h>
// 上电自检：快闪 3 下（说明程序跑起来了），串口报一句 hello 和基本信息，然后每秒心跳
// 任何项目出问题时，先烧这个：它能跑说明板子、线、工具链都没问题，问题在你的代码

void blinkFast(int times) {
  for (int i = 0; i < times; i++) {
    digitalWrite(LED_BUILTIN, HIGH); delay(100);
    digitalWrite(LED_BUILTIN, LOW);  delay(100);
  }
}

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  blinkFast(3);                    // 不依赖串口，灯闪就说明程序在跑

  Serial.begin(115200);
  delay(300);                      // 给 USB 串口一点时间
  Serial.println();
  Serial.println("==== hello, 自检开始 ====");
  Serial.print("编译时间: "); Serial.print(__DATE__); Serial.print(" "); Serial.println(__TIME__);
  Serial.print("主频: "); Serial.print(F_CPU / 1000000); Serial.println(" MHz");
  Serial.print("板载 LED 引脚编号: "); Serial.println(LED_BUILTIN);
#ifdef ARDUINO_ARCH_STM32
  Serial.println("架构: STM32duino");
#elif defined(ESP32)
  Serial.println("架构: ESP32");
#else
  Serial.println("架构: AVR 或其它");
#endif
  Serial.println("==== 自检通过，开始心跳 ====");
}

void loop() {
  static unsigned long n = 0;
  digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
  Serial.print("心跳 "); Serial.println(++n);
  delay(1000);
}

#include <Arduino.h>
#include <SPI.h>
// 用一根杜邦线把 PA7(MOSI) 和 PA6(MISO) 短接。发出去的字节应该原样收回来
// SPI1: SCK PA5 / MISO PA6 / MOSI PA7，片选随便挑一根普通 GPIO
const int CS_PIN = PA4;

void setup() {
  Serial.begin(115200);
  pinMode(CS_PIN, OUTPUT);
  digitalWrite(CS_PIN, HIGH);        // 片选高=不选中，低=选中
  SPI.begin();                       // 初始化 SPI1，默认 PA5/PA6/PA7
}

void loop() {
  // 把速度、位序、模式打包：1MHz，高位先发，模式 0（大多数芯片是模式 0）
  SPI.beginTransaction(SPISettings(1000000, MSBFIRST, SPI_MODE0));
  digitalWrite(CS_PIN, LOW);         // 选中"设备"（这里没设备，但流程照走）

  uint8_t sent[] = {0x55, 0xAA, 0x12, 0x34};
  int ok = 0;
  for (int i = 0; i < 4; i++) {
    uint8_t got = SPI.transfer(sent[i]);   // SPI 是全双工：发一个字节同时收一个字节
    Serial.print("发 0x"); Serial.print(sent[i], HEX);
    Serial.print(" 收 0x"); Serial.print(got, HEX);
    Serial.println(got == sent[i] ? "  OK" : "  不一致");
    if (got == sent[i]) ok++;
  }

  digitalWrite(CS_PIN, HIGH);        // 释放
  SPI.endTransaction();
  Serial.println(ok == 4 ? "SPI 自环通过" : "自环失败：检查 PA6-PA7 短接线");
  delay(2000);
}
// 接真设备时：把短接线拆掉，MOSI→设备 DI/SDI，MISO→设备 DO/SDO，SCK→CLK，CS→CS/SS
